#include "opeu/platform/build-identity.hpp"

// Generated by buildutil on every configure; included here and nowhere
// else, so the moving build time recompiles this one file.
#include "opeu/buildinfo.hpp"

#include <format>

namespace opeu::platform::detail::build_identity {

namespace {

constexpr auto THIS_BUILD{
  BuildIdentity{
                .version = OPEU_BUILD_VERSION,
                .commit  = OPEU_BUILD_COMMIT,
                .tag     = OPEU_BUILD_TAG,
                .time    = OPEU_BUILD_TIME,
                .dirty   = OPEU_BUILD_DIRTY != 0,
                .number  = OPEU_BUILD_NUMBER,
                }
};

}

auto ThisBuild() noexcept -> BuildIdentity const& {
  return THIS_BUILD;
}

auto Describe(BuildIdentity const& build) -> std::string {
  if (build.time.empty()) {
    return std::format("opeu {} (build {})", build.version, build.number);
  }
  return std::format("opeu {} (build {}, {})", build.version, build.number, build.time);
}

}
